CREATE TABLE family(id TEXT PRIMARY KEY,name TEXT,birthday TEXT,source TEXT);
CREATE TABLE profiles(id TEXT PRIMARY KEY,child_nickname TEXT,guardian_role TEXT CHECK(guardian_role IN ('father','mother','unknown')),source TEXT CHECK(source IN ('business_api','sql_mock')),as_of TEXT);
CREATE TABLE lessons(id TEXT PRIMARY KEY,business_date TEXT,title TEXT,body TEXT,completed INTEGER,as_of TEXT,source TEXT,binding_source TEXT,completion_source TEXT);
CREATE TABLE messages(source_id TEXT PRIMARY KEY,speaker TEXT,body TEXT,created_at TEXT,source TEXT,sha256 TEXT,visible INTEGER);
CREATE TABLE knowledge(id TEXT PRIMARY KEY,uri TEXT,body TEXT,sha256 TEXT,source TEXT);
CREATE TABLE deliveries(action_key TEXT PRIMARY KEY,body TEXT,status TEXT,created_at TEXT,source TEXT);
CREATE TABLE task_state(id TEXT PRIMARY KEY,status TEXT,payload TEXT);
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE memories(id TEXT PRIMARY KEY,memory_key TEXT,value TEXT,source_message_id TEXT,quote TEXT,source_sha256 TEXT,observed_at TEXT,recorded_at TEXT,status TEXT,source TEXT);
CREATE UNIQUE INDEX one_active_memory ON memories(memory_key) WHERE status='active';
CREATE TABLE daily_plans(business_date TEXT PRIMARY KEY,created_at TEXT,body TEXT,candidate_count INTEGER);
CREATE TABLE plan_candidates(id TEXT PRIMARY KEY,business_date TEXT,action TEXT,purpose TEXT,run_at TEXT,source TEXT);
CREATE TABLE context_snapshots(id TEXT PRIMARY KEY,business_date TEXT,sha256 TEXT,created_at TEXT,body TEXT);
CREATE TABLE internal_executions(candidate_id TEXT PRIMARY KEY,created_at TEXT,body TEXT);
CREATE TABLE media_assets(id TEXT PRIMARY KEY,kind TEXT,path TEXT,source TEXT);
CREATE TABLE events(id TEXT PRIMARY KEY,kind TEXT,payload TEXT,status TEXT,created_at TEXT,attempts INTEGER,dispatched_at TEXT,completed_at TEXT,retry_after TEXT);
CREATE TABLE memory_reviews(event_id TEXT PRIMARY KEY,reviewed_at TEXT,note TEXT);
CREATE TABLE source_checkpoints(context_id TEXT PRIMARY KEY,last_rowid INTEGER,last_scan_at TEXT,receipt TEXT);
CREATE TABLE source_seen(context_id TEXT,source_rowid INTEGER,terminal INTEGER,status TEXT,PRIMARY KEY(context_id,source_rowid));
